    }
    ListNode(int data1, ListNode *next1, ListNode* r)
    {
        val = data1;
        next = next1;
        random = r;
    }
};
*/

class Solution {
public:
    ListNode* create(ListNode *head){
        ListNode *dummy = new ListNode(-1);
        ListNode *temp = dummy;
        while(head){
            ListNode *node = new ListNode(head->val);
            temp->next=node;
            temp=temp->next;
            head=head->next;
        }return dummy->next;
    }
    ListNode* copyRandomList(ListNode* head) {
        ListNode *newhead = create(head);
        ListNode *temp = head;
        ListNode *newtemp = newhead;
        unordered_map<ListNode*,ListNode*> hmap;
        while(temp){
            hmap[newtemp]=temp;
            hmap[temp]=newtemp;
            temp=temp->next;
            newtemp=newtemp->next;
        }
        newtemp=newhead;
        while(newtemp){
            newtemp->random = hmap[hmap[newtemp]->random];
            newtemp=newtemp->next;
        }return newhead;
    }
};
